#!/usr/bin/env node
// Generates IDE-specific AI rule files from the base rules in .ai/rules.
//
//   node scripts/generate-ai-rules.mjs [target ...] [--check]
//
// With no target, every target listed in .ai/targets.json is generated.
// --check writes nothing and exits 1 when a generated file is stale.

import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const RULES_DIR = join(ROOT, '.ai/rules')
const TARGETS_FILE = join(ROOT, '.ai/targets.json')
const MARKER = 'AUTO-GENERATED by scripts/generate-ai-rules.mjs'
const BANNER = `<!-- ${MARKER} from .ai/rules — do not edit, run \`npm run rules:gen\` -->`

// ---------------------------------------------------------------- parsing

function parse_value(raw) {
  const value = raw.trim()
  if (value === 'true') return true
  if (value === 'false') return false
  // flow-style list, items quoted with ' or " (Prettier rewrites to ')
  if (value.startsWith('[')) {
    return (value.match(/(["'])(.*?)\1/g) ?? []).map(unquote)
  }
  return unquote(value)
}

function unquote(raw) {
  return raw.trim().replace(/^["']|["']$/g, '')
}

function parse_rule(file_name) {
  const source = readFileSync(join(RULES_DIR, file_name), 'utf8')
  const match = source.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  if (!match) throw new Error(`${file_name}: missing frontmatter`)

  const meta = {}
  for (const line of match[1].split('\n')) {
    if (!line.trim() || line.trimStart().startsWith('#')) continue
    const index = line.indexOf(':')
    meta[line.slice(0, index).trim()] = parse_value(line.slice(index + 1))
  }
  if (!meta.title || !meta.description) {
    throw new Error(`${file_name}: title and description are required`)
  }

  return {
    // "20-naming.md" -> "20-naming"
    name: file_name.replace(/\.md$/, ''),
    title: meta.title,
    description: meta.description,
    globs: meta.globs ?? [],
    always_apply: meta.always_apply ?? true,
    body: match[2].trim(),
  }
}

function load_rules() {
  return readdirSync(RULES_DIR)
    .filter((file_name) => file_name.endsWith('.md'))
    .sort()
    .map(parse_rule)
}

// ---------------------------------------------------------------- helpers

function scope_note(rule) {
  if (rule.always_apply || !rule.globs.length) return ''
  return `> Applies to: ${rule.globs.map((glob) => `\`${glob}\``).join(', ')}\n\n`
}

function concat_rules(rules, heading) {
  const sections = rules.map((rule) => scope_note(rule) + rule.body)
  return [
    BANNER,
    '',
    `# ${heading}`,
    '',
    ...sections.join('\n\n---\n\n').split('\n'),
    '',
  ].join('\n')
}

function frontmatter(fields) {
  const lines = Object.entries(fields)
    .filter(([, value]) => value !== undefined)
    .map(([key, value]) => `${key}: ${value}`)
  return ['---', ...lines, '---'].join('\n')
}

// ---------------------------------------------------------------- targets
// Each target returns { files: { path: content }, dirs: [dir] }.
// `dirs` are folders the target owns: stale generated files there get removed.

const targets = {
  claude: (rules) => ({
    files: {
      'CLAUDE.md': concat_rules(rules, 'Project rules for Claude Code'),
    },
  }),

  agents: (rules) => ({
    files: { 'AGENTS.md': concat_rules(rules, 'Project rules for AI agents') },
  }),

  cursor: (rules) => ({
    dirs: ['.cursor/rules'],
    files: Object.fromEntries(
      rules.map((rule) => [
        `.cursor/rules/${rule.name}.mdc`,
        [
          frontmatter({
            description: rule.description,
            globs: rule.globs.length ? rule.globs.join(',') : undefined,
            alwaysApply: rule.always_apply,
          }),
          BANNER,
          '',
          rule.body,
          '',
        ].join('\n'),
      ]),
    ),
  }),

  copilot: (rules) => {
    const global_rules = rules.filter(
      (rule) => rule.always_apply || !rule.globs.length,
    )
    const scoped_rules = rules.filter((rule) => !global_rules.includes(rule))
    return {
      dirs: ['.github/instructions'],
      files: {
        '.github/copilot-instructions.md': concat_rules(
          global_rules,
          'Project rules for GitHub Copilot',
        ),
        ...Object.fromEntries(
          scoped_rules.map((rule) => [
            `.github/instructions/${rule.name}.instructions.md`,
            [
              frontmatter({ applyTo: `"${rule.globs.join(',')}"` }),
              BANNER,
              '',
              rule.body,
              '',
            ].join('\n'),
          ]),
        ),
      },
    }
  },

  windsurf: (rules) => ({
    dirs: ['.windsurf/rules'],
    files: Object.fromEntries(
      rules.map((rule) => {
        const scoped = !rule.always_apply && rule.globs.length
        return [
          `.windsurf/rules/${rule.name}.md`,
          [
            frontmatter({
              trigger: scoped ? 'glob' : 'always_on',
              description: rule.description,
              globs: scoped ? rule.globs.join(',') : undefined,
            }),
            BANNER,
            '',
            rule.body,
            '',
          ].join('\n'),
        ]
      }),
    ),
  }),
}

// ---------------------------------------------------------------- main

function stale_files(dir, keep) {
  const absolute_dir = join(ROOT, dir)
  if (!existsSync(absolute_dir)) return []
  return readdirSync(absolute_dir)
    .map((file_name) => join(dir, file_name))
    .filter((path) => !keep.has(path))
    .filter((path) => readFileSync(join(ROOT, path), 'utf8').includes(MARKER))
}

function main() {
  const args = process.argv.slice(2)
  const check = args.includes('--check')
  const requested = args.filter((arg) => !arg.startsWith('--'))
  const selected = requested.length
    ? requested
    : JSON.parse(readFileSync(TARGETS_FILE, 'utf8')).targets

  const unknown = selected.filter((name) => !targets[name])
  if (unknown.length) {
    console.error(
      `Unknown target(s): ${unknown.join(', ')}. Available: ${Object.keys(targets).join(', ')}`,
    )
    process.exit(1)
  }

  const rules = load_rules()
  const problems = []

  for (const name of selected) {
    const { files, dirs = [] } = targets[name](rules)
    const keep = new Set(Object.keys(files))

    for (const [path, content] of Object.entries(files)) {
      const absolute_path = join(ROOT, path)
      const current = existsSync(absolute_path)
        ? readFileSync(absolute_path, 'utf8')
        : null
      if (current === content) continue
      if (check) {
        problems.push(`${current === null ? 'missing' : 'stale'}: ${path}`)
        continue
      }
      mkdirSync(dirname(absolute_path), { recursive: true })
      writeFileSync(absolute_path, content)
      console.log(`[${name}] wrote ${path}`)
    }

    for (const path of dirs.flatMap((dir) => stale_files(dir, keep))) {
      if (check) {
        problems.push(`orphan: ${path}`)
        continue
      }
      rmSync(join(ROOT, path))
      console.log(`[${name}] removed ${path}`)
    }
  }

  if (check && problems.length) {
    console.error(
      `AI rules out of date (run \`npm run rules:gen\`):\n  ${problems.join('\n  ')}`,
    )
    process.exit(1)
  }
  console.log(
    check
      ? 'AI rules up to date.'
      : `Generated from ${relative(ROOT, RULES_DIR)} (${rules.length} rules).`,
  )
}

main()
